schema_ddl:
CREATE TABLE fornitori (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ragione_sociale TEXT NOT NULL,
    partita_iva TEXT NOT NULL UNIQUE
);

CREATE TABLE ordini_fornitori (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    fornitore_id INT NOT NULL REFERENCES fornitori(id),
    data_ordine DATE NOT NULL DEFAULT CURRENT_DATE,
    stato TEXT NOT NULL CHECK (stato IN ('emesso', 'evaso', 'annullato'))
);

CREATE TABLE articoli (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codice_articolo TEXT NOT NULL UNIQUE,
    descrizione TEXT NOT NULL,
    costo_unitario NUMERIC(10,2) NOT NULL CHECK (costo_unitario >= 0)
);

CREATE TABLE dettagli_ordini (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ordine_id INT NOT NULL REFERENCES ordini_fornitori(id),
    articolo_id INT NOT NULL REFERENCES articoli(id),
    quantita INT NOT NULL CHECK (quantita > 0),
    prezzo_concordato NUMERIC(10,2) NOT NULL CHECK (prezzo_concordato >= 0)
);
